using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using System;using System.Linq;
public static class PolishLaunchRoom{
 public static object Run(){var seq=UnityEngine.Object.FindFirstObjectByType<HangarLaunchSequence>();var root=seq.transform;var terrain=Terrain.activeTerrain;var data=terrain.terrainData;Undo.RecordObject(data,"Level electrical room foundation");int res=data.heightmapResolution;var heights=data.GetHeights(0,0,res,res);int changed=0;
 for(int z=0;z<res;z++)for(int x=0;x<res;x++){var world=terrain.transform.position+new Vector3(x/(float)(res-1)*data.size.x,0,z/(float)(res-1)*data.size.z);var p=root.InverseTransformPoint(world);if(Mathf.Abs(p.x)>4.8f||p.z<-.4f||p.z>12.8f)continue;heights[z,x]=(root.position.y-.15f-terrain.transform.position.y)/data.size.y;changed++;}data.SetHeights(0,0,heights);EditorUtility.SetDirty(data);
 int meshes=0;foreach(var r in UnityEngine.Object.FindObjectsByType<MeshRenderer>(FindObjectsSortMode.None)){if(!r.name.ToLower().Contains("grass"))continue;var p=root.InverseTransformPoint(r.bounds.center);if(Mathf.Abs(p.x)>25||p.z< -20||p.z>35)continue;var f=r.GetComponent<MeshFilter>();if(f==null||f.sharedMesh==null)continue;var source=f.sharedMesh;var mesh=UnityEngine.Object.Instantiate(source);var verts=mesh.vertices;bool any=false;for(int sm=0;sm<mesh.subMeshCount;sm++){var tr=mesh.GetTriangles(sm);var kept=new System.Collections.Generic.List<int>();for(int i=0;i<tr.Length;i+=3){var pt=root.InverseTransformPoint(f.transform.TransformPoint((verts[tr[i]]+verts[tr[i+1]]+verts[tr[i+2]])/3));if(Mathf.Abs(pt.x)<4.6f&&pt.z>-.3f&&pt.z<12.6f){any=true;continue;}kept.Add(tr[i]);kept.Add(tr[i+1]);kept.Add(tr[i+2]);}mesh.SetTriangles(kept,sm);}if(any){mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,"Assets/LaunchRoom/Cleared grass "+meshes+++".asset");f.sharedMesh=mesh;EditorUtility.SetDirty(f);}else UnityEngine.Object.DestroyImmediate(mesh);}
 foreach(var text in seq.GetComponentsInChildren<TextMesh>()){if(text.text.StartsWith("DANGER")){text.transform.localScale=new Vector3(.25f,1f/4.8f,1f/.18f);text.characterSize=.13f;text.transform.localRotation=Quaternion.identity;}else if(text.text.StartsWith("ELECTRICAL"))text.transform.localRotation=Quaternion.identity;}
 seq.revealDoor.localPosition=new Vector3(0,2.4f,5.4f);seq.rocketDoor.localRotation*=Quaternion.Euler(0,105,0);seq.roomLight.enabled=false;seq.lampGlow.enabled=false;
 var glow=seq.lampGlow.sharedMaterial;glow.SetColor("_EmissiveColor",new Color(5,3.5f,1.8f));EditorUtility.SetDirty(glow);
 var cam=GameObject.Find("Launch room inspection camera");if(cam!=null)UnityEngine.Object.DestroyImmediate(cam);
 EditorSceneManager.MarkSceneDirty(seq.gameObject.scene);EditorSceneManager.SaveOpenScenes();AssetDatabase.SaveAssets();Physics.SyncTransforms();return "Foundation samples="+changed+", grass meshes cleared="+meshes;
 }
}
